//! Let's Encrypt / certbot orchestration.
//!
//! Ports `server/le_certbot`. Vreckan serves its web UI over TLS. By
//! default it uses a self-signed certificate (generated by `tls.rs`). When
//! Let's Encrypt is enabled (via `VRECKAN_LE_*` env vars or the admin
//! Certificates page), this module issues and renews real certificates by
//! running the official `certbot/dns-cloudflare` image as a *transient*
//! container: it is started, waits for it to exit, streams its logs on
//! failure, and removes it.
//!
//! The certbot container mounts the app's `/data/le` storage directly (the
//! same bind mount or named volume the app uses for that path, auto-detected
//! at runtime). Certificates therefore persist across container
//! re-creations and are readable by the app without a separate host bind
//! mount.

use std::pin::Pin;
use std::sync::{Arc, Mutex};

use async_trait::async_trait;
use bollard::container::LogOutput;
use bollard::errors::Error;
use bollard::models::{
    ContainerCreateBody, ContainerCreateResponse, ContainerInspectResponse,
    ContainerWaitResponse, HostConfig,
};
use bollard::query_parameters::{CreateContainerOptions, LogsOptions, RemoveContainerOptions};
use bollard::Docker;
use der::Decode;
use futures_util::{Stream, StreamExt};
use rand::RngCore;
use serde_json::Value;
use tracing::{info, warn};

use crate::state::AppState;

/// The official certbot image with the Cloudflare DNS plugin bundled.
pub const CERTBOT_IMAGE: &str = "certbot/dns-cloudflare:latest";
/// Named volume shared between the certbot container (/etc/letsencrypt) and
/// the app container (/data/le).
pub const LE_VOLUME: &str = "vreckan-le";
/// Where the app reads certbot-issued certificates from (the shared volume).
/// A `static` (not a plain `const`) so tests can point it at a temp tree —
/// mirroring the Python test's `monkeypatch.setattr(le_certbot, "LE_APP_CERT_DIR", ...)`.
/// `None` means "use the default `/data/le`".
pub static LE_APP_CERT_DIR: std::sync::RwLock<Option<String>> = std::sync::RwLock::new(None);
/// Where the app looks for a host-provided /etc/letsencrypt (checked first).
/// A `static` so tests can point it at a temp tree (mirrors the Python
/// `monkeypatch.setattr(le_certbot, "LE_HOST_CERT_DIR", ...)`).
/// `None` means "use the default `/etc/letsencrypt`".
pub static LE_HOST_CERT_DIR: std::sync::RwLock<Option<String>> = std::sync::RwLock::new(None);
/// certbot's default paths *inside* the certbot container.
pub const CERTBOT_CERT_DIR: &str = "/etc/letsencrypt";
pub const CERTBOT_CREDENTIALS: &str = "/etc/letsencrypt/cloudflare.ini";

/// The effective app-side cert dir (test override or the default `/data/le`).
pub fn app_cert_dir() -> String {
    LE_APP_CERT_DIR
        .read()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone()
        .unwrap_or_else(|| "/data/le".to_string())
}
/// The effective host-side cert dir (test override or the default
/// `/etc/letsencrypt`).
pub fn host_cert_dir() -> String {
    LE_HOST_CERT_DIR
        .read()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone()
        .unwrap_or_else(|| "/etc/letsencrypt".to_string())
}

/// The effective Let's Encrypt configuration (DB-over-env-over-default),
/// mirroring the `_Cfg` object returned by Python's `effective_le_config()`.
/// Both the startup path and the background renewal loop read from this so a
/// value edited on the admin Certificates page takes effect without a
/// container restart.
#[derive(Clone, Debug)]
pub struct LeConfig {
    pub le_enabled: bool,
    pub le_domains: String,
    pub le_auth: String,
    pub le_staging: bool,
    pub le_cloudflare_email: String,
    pub le_cloudflare_token: String,
    pub le_auto_renew: bool,
    pub le_renew_check_hours: i64,
    pub le_renew_before_days: i64,
}

/// Build the *effective* LE settings (``app_settings`` DB override → env →
/// default). Mirrors `effective_le_config`.
pub async fn effective_le_config(state: &AppState) -> LeConfig {
    let s = &state.settings;
    let db = &state.db;
    let le_enabled = s.get_setting(db, "le_enabled").await.as_bool().unwrap_or(false);
    let le_domains = s.get_setting(db, "le_domains").await.as_str().unwrap_or("").to_string();
    let le_auth_raw = s.get_setting(db, "le_auth").await.as_str().unwrap_or("").to_string();
    let le_auth = if le_auth_raw.is_empty() {
        "dns-cloudflare".to_string()
    } else {
        le_auth_raw
    };
    let le_staging = s.get_setting(db, "le_staging").await.as_bool().unwrap_or(false);
    let le_cloudflare_email = s.get_setting(db, "le_cloudflare_email").await.as_str().unwrap_or("").to_string();
    let le_cloudflare_token = s.get_setting(db, "le_cloudflare_token").await.as_str().unwrap_or("").to_string();
    let le_auto_renew = s.get_setting(db, "le_auto_renew").await.as_bool().unwrap_or(false);
    let le_renew_check_hours = s.get_setting(db, "le_renew_check_hours").await.as_i64().unwrap_or(0);
    let le_renew_before_days = s.get_setting(db, "le_renew_before_days").await.as_i64().unwrap_or(0);
    LeConfig {
        le_enabled,
        le_domains,
        le_auth,
        le_staging,
        le_cloudflare_email,
        le_cloudflare_token,
        le_auto_renew,
        le_renew_check_hours,
        le_renew_before_days,
    }
}

/// A minimal, injectable Docker client surface — just the calls
/// `run_certbot`/`app_le_mount` need. `bollard::Docker` implements it, and
/// tests supply a fake so the suite never needs a Docker daemon (mirrors the
/// Python test's `FakeClient`/`FakeContainers`).
#[async_trait]
pub trait CertbotDocker: Send + Sync {
    async fn create_container(
        &self,
        options: Option<CreateContainerOptions>,
        config: ContainerCreateBody,
    ) -> Result<ContainerCreateResponse, Error>;
    async fn start_container(&self, name: &str) -> Result<(), Error>;
    fn wait_container(&self, name: &str) -> Pin<Box<dyn Stream<Item = Result<ContainerWaitResponse, Error>> + Send>>;
    fn logs(&self, name: &str) -> Pin<Box<dyn Stream<Item = Result<LogOutput, Error>> + Send>>;
    async fn remove_container(&self, name: &str) -> Result<(), Error>;
    async fn inspect_container(
        &self,
        name: &str,
    ) -> Result<ContainerInspectResponse, Error>;
}

#[async_trait]
impl CertbotDocker for Docker {
    async fn create_container(
        &self,
        options: Option<CreateContainerOptions>,
        config: ContainerCreateBody,
    ) -> Result<ContainerCreateResponse, Error> {
        Docker::create_container(self, options, config).await
    }
    async fn start_container(&self, name: &str) -> Result<(), Error> {
        Docker::start_container(self, name, None).await
    }
    fn wait_container(&self, name: &str) -> Pin<Box<dyn Stream<Item = Result<ContainerWaitResponse, Error>> + Send>> {
        Box::pin(Docker::wait_container(self, name, None))
    }
    fn logs(&self, name: &str) -> Pin<Box<dyn Stream<Item = Result<LogOutput, Error>> + Send>> {
        Box::pin(Docker::logs(self, name, Some(LogsOptions { stdout: true, stderr: true, ..Default::default() })))
    }
    async fn remove_container(&self, name: &str) -> Result<(), Error> {
        Docker::remove_container(self, name, Some(RemoveContainerOptions { force: true, ..Default::default() })).await
    }
    async fn inspect_container(
        &self,
        name: &str,
    ) -> Result<ContainerInspectResponse, Error> {
        Docker::inspect_container(self, name, None).await
    }
}

/// A process-wide override for the certbot Docker client, so tests can inject
/// a fake without a daemon (mirrors the Python test's `client=FakeClient()`
/// argument). `None` means "connect to the real daemon".
pub static FAKE_CERTBOT_CLIENT: Mutex<Option<Arc<dyn CertbotDocker>>> = Mutex::new(None);

/// Resolve the Docker client to use: the test override if set, else the real
/// daemon.
async fn resolve_client() -> Option<Arc<dyn CertbotDocker>> {
    if let Some(c) = FAKE_CERTBOT_CLIENT
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone()
    {
        return Some(c);
    }
    match Docker::connect_with_local_defaults() {
        Ok(c) => Some(Arc::new(c)),
        Err(e) => {
            warn!("Could not connect to Docker for certbot: {e}");
            None
        }
    }
}

fn primary_domain(domains: &[String]) -> &str {
    domains.first().map(|s| s.as_str()).unwrap_or("")
}

/// Return the cert/key paths for the given domains, or `None` if no
/// certificate is present. The host `/etc/letsencrypt` is checked first; the
/// shared-volume path (`/data/le`) is the fallback. Mirrors `cert_paths`.
fn cert_paths(domains: &[String]) -> Option<(String, String, String)> {
    let primary = primary_domain(domains);
    if primary.is_empty() {
        return None;
    }
    let host = host_cert_dir();
    let app = app_cert_dir();
    for base in [host, app] {
        let cert = format!("{base}/live/{primary}/cert.pem");
        let key = format!("{base}/live/{primary}/privkey.pem");
        if std::path::Path::new(&cert).is_file() && std::path::Path::new(&key).is_file() {
            return Some((cert, key, base));
        }
    }
    None
}

/// Parse a PEM certificate and return its notAfter as a Unix timestamp
/// (seconds), or `None` if it cannot be read/parsed. Mirrors `cert_expiry`.
pub fn cert_expiry(cert_path: &str) -> Option<i64> {
    let pem = std::fs::read(cert_path).ok()?;
    let mut reader = std::io::Cursor::new(pem);
    let cert = rustls_pemfile::certs(&mut reader).next()?.ok()?;
    let x509 = x509_cert::Certificate::from_der(cert.as_ref()).ok()?;
    let not_after = x509.tbs_certificate.validity.not_after;
    Some(not_after.to_unix_duration().as_secs() as i64)
}

/// Describe the current certificate for the given domains. Mirrors
/// `cert_status`.
pub fn cert_status(domains: &[String]) -> Value {
    let Some((cert, key, base)) = cert_paths(domains) else {
        return serde_json::json!({
            "present": false,
            "source": null,
            "cert": null,
            "key": null,
            "expiry": null,
            "days_remaining": null,
            "valid": false,
        });
    };
    let exp = cert_expiry(&cert);
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let (days_remaining, valid) = match exp {
        Some(e) => (Some((e - now) / 86400), e > now),
        None => (None, false),
    };
    let source = if base == host_cert_dir() { "host" } else { "volume" };
    let expiry = exp.map(|e| {
        chrono::DateTime::from_timestamp(e, 0)
            .map(|dt| dt.to_rfc3339())
            .unwrap_or_default()
    });
    serde_json::json!({
        "present": true,
        "source": source,
        "cert": cert,
        "key": key,
        "expiry": expiry,
        "days_remaining": days_remaining,
        "valid": valid,
    })
}

/// True when the cert should be renewed: it is present and expires within
/// `renew_before_days` days (or is already expired). Mirrors `needs_renewal`.
pub fn needs_renewal(days_remaining: Option<i64>, renew_before_days: i64) -> bool {
    match days_remaining {
        Some(d) => d <= renew_before_days,
        None => false,
    }
}

/// Write the Cloudflare credentials file into the shared volume. Mirrors
/// `write_cloudflare_credentials`.
pub fn write_cloudflare_credentials(email: &str, token: &str) -> String {
    let base = app_cert_dir();
    let path = format!("{base}/cloudflare.ini");
    let _ = std::fs::create_dir_all(&base);
    let mut content = String::new();
    if !token.is_empty() {
        content.push_str(&format!("dns_cloudflare_api_token = {token}\n"));
    }
    if !email.is_empty() && token.is_empty() {
        content.push_str(&format!("dns_cloudflare_email = {email}\n"));
    }
    let _ = std::fs::write(&path, content);
    path
}

/// Build the certbot command-line arguments. Mirrors `certbot_args`.
pub fn certbot_args(auth: &str, domains: &[String], staging: bool, renew: bool) -> Vec<String> {
    let mut args: Vec<String> = Vec::new();
    args.push(if renew { "renew" } else { "certonly" }.to_string());
    args.push("--non-interactive".to_string());
    args.push("--agree-tos".to_string());
    args.push("--register-unsafely-without-email".to_string());
    if staging {
        args.push("--staging".to_string());
    }
    if auth == "http-01" {
        args.push("--http-01".to_string());
        args.push(format!("--webroot-root={CERTBOT_CERT_DIR}"));
    } else {
        args.push("--dns-cloudflare".to_string());
        args.push(format!("--dns-cloudflare-credentials={CERTBOT_CREDENTIALS}"));
    }
    for d in domains {
        args.push("-d".to_string());
        args.push(d.clone());
    }
    args
}

/// Detect how the app container's `/data/le` is backed and return the mount
/// spec (a host path or a named-volume name) that a transient certbot
/// container should bind at `/etc/letsencrypt`. Mirrors `_app_le_mount`.
async fn app_le_mount(client: &dyn CertbotDocker) -> String {
    let hostname = std::env::var("HOSTNAME").unwrap_or_default();
    if !hostname.is_empty() {
        if let Ok(ci) = client.inspect_container(&hostname).await {
            if let Some(mounts) = &ci.mounts {
                for m in mounts {
                    if m.destination.as_deref() == Some("/data") {
                        if m.typ.as_deref() == Some("volume") {
                            return m.name.clone().unwrap_or_else(|| LE_VOLUME.to_string());
                        }
                        if let Some(src) = &m.source {
                            if !src.is_empty() {
                                return format!("{}/le", src.trim_end_matches('/'));
                            }
                        }
                    }
                }
            }
        }
    }
    LE_VOLUME.to_string()
}

/// Run a transient certbot container with the given arguments. Mirrors
/// `run_certbot`. Returns `{"ok": bool, "exit_code": i64|null, "logs": str}`.
pub async fn run_certbot(
    client: &dyn CertbotDocker,
    args: &[String],
    volume: &str,
    timeout: u64,
) -> Value {
    let volume = if volume == LE_VOLUME {
        app_le_mount(client).await
    } else {
        volume.to_string()
    };
    let body = ContainerCreateBody {
        image: Some(CERTBOT_IMAGE.to_string()),
        cmd: Some(args.to_vec()),
        host_config: Some(HostConfig {
            binds: Some(vec![format!("{volume}:{CERTBOT_CERT_DIR}:rw")]),
            ..Default::default()
        }),
        ..Default::default()
    };
    let name = format!("vreckan-certbot-{}", random_suffix());
    let create_opts = CreateContainerOptions { name: Some(name.clone()), ..Default::default() };
    let container_id = match client
        .create_container(Some(create_opts), body)
        .await
    {
        Ok(c) => c.id,
        Err(e) => {
            warn!("certbot container create error: {e}");
            return serde_json::json!({ "ok": false, "exit_code": null, "logs": e.to_string() });
        }
    };
    let _ = client.start_container(&container_id).await;

    // Wait for the container to exit (bounded by `timeout`).
    let mut wait_stream = client.wait_container(&container_id);
    let exit_code = match tokio::time::timeout(
        std::time::Duration::from_secs(timeout),
        wait_stream.next(),
    )
    .await
    {
        Ok(Some(Ok(r))) => Some(r.status_code),
        _ => None,
    };

    // Collect the logs (stdout + stderr).
    let mut logs = String::new();
    let mut log_stream = client.logs(&container_id);
    while let Some(item) = log_stream.next().await {
        if let Ok(out) = item {
            logs.push_str(&out.to_string());
        }
    }

    let ok = exit_code == Some(0);
    if !ok {
        warn!("certbot exited {:?}:\n{logs}", exit_code);
    }
    let _ = client.remove_container(&container_id).await;
    serde_json::json!({ "ok": ok, "exit_code": exit_code, "logs": logs })
}

fn random_suffix() -> String {
    let mut buf = [0u8; 4];
    rand::rng().fill_bytes(&mut buf);
    hex::encode(buf)
}

/// Startup: make sure a valid Let's Encrypt certificate exists. Mirrors
/// `ensure_le_cert`. Returns a status dict plus an `issued` flag.
pub async fn ensure_le_cert(cfg: &LeConfig) -> Value {
    let domains: Vec<String> = cfg
        .le_domains
        .split(',')
        .map(|d| d.trim().to_string())
        .filter(|d| !d.is_empty())
        .collect();
    if !cfg.le_enabled {
        let mut result = cert_status(&domains);
        if let Some(obj) = result.as_object_mut() {
            obj.insert("issued".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(false));
        }
        return result;
    }
    if domains.is_empty() {
        warn!("LE enabled but no domains configured (le_domains).");
        let mut result = cert_status(&domains);
        if let Some(obj) = result.as_object_mut() {
            obj.insert("issued".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(true));
        }
        return result;
    }
    let status = cert_status(&domains);
    if status.get("valid").and_then(|v| v.as_bool()).unwrap_or(false) {
        info!(
            "LE certificate valid until {} ({}d).",
            status.get("expiry").and_then(|v| v.as_str()).unwrap_or("?"),
            status.get("days_remaining").and_then(|v| v.as_i64()).unwrap_or(0)
        );
        let mut result = status;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("issued".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(true));
        }
        return result;
    }
    // (Re)issue.
    if cfg.le_auth != "http-01" {
        if cfg.le_cloudflare_token.is_empty() {
            warn!("LE DNS-01 enabled but Cloudflare API token not set.");
            let mut result = status;
            if let Some(obj) = result.as_object_mut() {
                obj.insert("issued".into(), Value::Bool(false));
                obj.insert("enabled".into(), Value::Bool(true));
            }
            return result;
        }
        write_cloudflare_credentials(&cfg.le_cloudflare_email, &cfg.le_cloudflare_token);
    }
    let args = certbot_args(&cfg.le_auth, &domains, cfg.le_staging, false);
    let Some(client) = resolve_client().await else {
        let mut result = status;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("issued".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(true));
        }
        return result;
    };
    let result = run_certbot(client.as_ref(), &args, LE_VOLUME, 300).await;
    let status = cert_status(&domains);
    let issued = result.get("ok").and_then(|v| v.as_bool()).unwrap_or(false);
    let mut result = status;
    if let Some(obj) = result.as_object_mut() {
        obj.insert("issued".into(), Value::Bool(issued));
        obj.insert("enabled".into(), Value::Bool(true));
    }
    result
}

/// Background renewal: renew the cert if it is within the renewal window.
/// Mirrors `renew_le_cert`.
pub async fn renew_le_cert(cfg: &LeConfig) -> Value {
    let domains: Vec<String> = cfg
        .le_domains
        .split(',')
        .map(|d| d.trim().to_string())
        .filter(|d| !d.is_empty())
        .collect();
    if !cfg.le_enabled || domains.is_empty() {
        let mut result = cert_status(&domains);
        if let Some(obj) = result.as_object_mut() {
            obj.insert("renewed".into(), Value::Bool(false));
            obj.insert("due".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(cfg.le_enabled));
        }
        return result;
    }
    let status = cert_status(&domains);
    let due = needs_renewal(
        status.get("days_remaining").and_then(|v| v.as_i64()),
        cfg.le_renew_before_days,
    );
    if !due {
        let mut result = status;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("renewed".into(), Value::Bool(false));
            obj.insert("due".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(true));
        }
        return result;
    }
    if cfg.le_auth != "http-01" {
        if cfg.le_cloudflare_token.is_empty() {
            warn!("LE DNS-01 enabled but Cloudflare API token not set.");
            let mut result = status;
            if let Some(obj) = result.as_object_mut() {
                obj.insert("renewed".into(), Value::Bool(false));
                obj.insert("due".into(), Value::Bool(true));
                obj.insert("enabled".into(), Value::Bool(true));
            }
            return result;
        }
        write_cloudflare_credentials(&cfg.le_cloudflare_email, &cfg.le_cloudflare_token);
    }
    let args = certbot_args(&cfg.le_auth, &domains, cfg.le_staging, true);
    let Some(client) = resolve_client().await else {
        let mut result = status;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("renewed".into(), Value::Bool(false));
            obj.insert("due".into(), Value::Bool(true));
            obj.insert("enabled".into(), Value::Bool(true));
        }
        return result;
    };
    let result = run_certbot(client.as_ref(), &args, LE_VOLUME, 300).await;
    let status = cert_status(&domains);
    let renewed = result.get("ok").and_then(|v| v.as_bool()).unwrap_or(false);
    let mut result = status;
    if let Some(obj) = result.as_object_mut() {
        obj.insert("renewed".into(), Value::Bool(renewed));
        obj.insert("due".into(), Value::Bool(true));
        obj.insert("enabled".into(), Value::Bool(true));
    }
    result
}

/// Periodically check the Let's Encrypt certificate and renew it when it is
/// within the configured renewal window. The interval and window are read
/// fresh on each iteration (admin-editable), so changes take effect without a
/// restart. No-op when LE is disabled or auto-renew is off. Mirrors
/// `background_le_renewal_job` in `api`.
pub async fn background_le_renewal_job(state: AppState) {
    loop {
        // Read the effective config fresh each iteration (admin-editable), so
        // changes take effect without a restart.
        let cfg = effective_le_config(&state).await;
        if !(cfg.le_enabled && cfg.le_auto_renew) {
            tokio::time::sleep(std::time::Duration::from_secs(300)).await;
            continue;
        }
        let result = renew_le_cert(&cfg).await;
        if result.get("due").and_then(|v| v.as_bool()).unwrap_or(false) {
            info!(
                "LE certificate renewal {} ({}d remaining).",
                if result.get("renewed").and_then(|v| v.as_bool()).unwrap_or(false) {
                    "succeeded"
                } else {
                    "failed"
                },
                result.get("days_remaining").and_then(|v| v.as_i64()).unwrap_or(0)
            );
        }
        tokio::time::sleep(std::time::Duration::from_secs(
            cfg.le_renew_check_hours.saturating_mul(3600) as u64,
        ))
        .await;
    }
}
